-- NRSV-CE OLD TESTAMENT BIBLE VERSES (PART 14)

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 1, 1, 'In the third year of the reign of King Jehoiakim of Judah, King Nebuchadnezzar of Babylon came to Jerusalem and besieged it.', 'en', 'NRSV-CE', 'Four Young Israelites at the Babylonian Court'),
(27, 'Dan', 'Daniel', 1, 2, 'The Lord let King Jehoiakim of Judah fall into his power, as well as some of the vessels of the house of God. These he brought to the land of Shinar, and placed the vessels in the treasury of his gods.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 3, 'Then the king commanded his palace master Ashpenaz to bring some of the Israelites of the royal family and of the nobility,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 4, 'young men without physical defect and handsome, versed in every branch of wisdom, endowed with knowledge and insight, and competent to serve in the king"s palace; they were to be taught the literature and language of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 5, 'The king assigned them a daily portion of the royal rations of food and wine. They were to be educated for three years, so that at the end of that time they could be stationed in the king"s court.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 6, 'Among them were Daniel, Hananiah, Mishael, and Azariah, from the tribe of Judah.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 7, 'The palace master gave them other names: Daniel he called Belteshazzar, Hananiah he called Shadrach, Mishael he called Meshach, and Azariah he called Abednego.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 8, 'But Daniel resolved that he would not defile himself with the royal rations of food and wine; so he asked the palace master to allow him not to defile himself.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 9, 'Now God allowed Daniel to receive favor and compassion from the palace master.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 10, 'The palace master said to Daniel, "I am afraid of my lord the king; he has appointed your food and your drink. If he should see you in poorer condition than the other young men of your own age, you would endanger my head with the king."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 11, 'Then Daniel asked the guard whom the palace master had appointed over Daniel, Hananiah, Mishael, and Azariah:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 12, '"Please test your servants for ten days. Let us be given vegetables to eat and water to drink.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 13, 'You can then compare our appearance with the appearance of the young men who eat the royal rations, and deal with your servants according to what you observe."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 14, 'So he agreed to this proposal and tested them for ten days.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 15, 'At the end of ten days it was observed that they appeared better and fatter than all the young men who had been eating the royal rations.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 16, 'So the guard continued to withdraw their royal rations and the wine they were to drink, and gave them vegetables.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 17, 'To these four young men God gave knowledge and skill in every aspect of literature and wisdom; Daniel also had insight into all visions and dreams.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 18, 'At the end of the time that the king had set for them to be brought in, the palace master brought them into the presence of Nebuchadnezzar,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 19, 'and the king spoke with them. And among them all, no one was found to compare with Daniel, Hananiah, Mishael, and Azariah; therefore they were stationed in the king"s court.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 20, 'In every matter of wisdom and understanding concerning which the king inquired of them, he found them ten times better than all the magicians and enchanters in his whole kingdom.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 1, 21, 'And Daniel continued there until the first year of King Cyrus.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 2, 1, 'In the second year of Nebuchadnezzar"s reign, Nebuchadnezzar dreamed such dreams that his spirit was troubled and his sleep left him.', 'en', 'NRSV-CE', 'Nebuchadnezzar"s Dream'),
(27, 'Dan', 'Daniel', 2, 2, 'So the king commanded that the magicians, the enchanters, the sorcerers, and the Chaldeans be summoned to tell the king his dreams. When they came in and stood before the king,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 3, 'he said to them, "I have had such a dream that my spirit is troubled by the desire to understand it."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 4, 'The Chaldeans said to the king (in Aramaic), "O king, live forever! Tell your servants the dream, and we will reveal the interpretation."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 5, 'The king answered the Chaldeans, "This is a public decree: if you do not tell me both the dream and its interpretation, you shall be torn limb from limb, and your houses shall be laid in ruins.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 6, 'But if you do tell me the dream and its interpretation, you shall receive from me gifts and rewards and great honor. Therefore tell me the dream and its interpretation."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 7, 'They answered a second time, "Let the king first tell his servants the dream, then we can give its interpretation."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 8, 'The king answered, "I know with certainty that you are trying to gain time, because you see I have firmly decreed:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 9, 'if you do not tell me the dream, there is but one verdict for you. You have agreed to speak lying and misleading words to me until things take a turn. Therefore, tell me the dream, and I shall know that you can give me its interpretation."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 10, 'The Chaldeans answered the king, "There is no one on earth who can reveal what the king demands! In fact no king, however great and powerful, has ever asked such a thing of any magician or enchanter or Chaldean.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 11, 'The thing that the king is asking is too difficult, and no one can reveal it to the king except the gods, whose dwelling is not with mortals."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 12, 'Because of this the king flew into a violent rage and commanded that all the wise men of Babylon be destroyed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 13, 'The decree was issued, and the wise men were about to be executed; and they looked for Daniel and his companions, to execute them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 14, 'Then Daniel responded with prudence and discretion to Arioch, the king"s chief executioner, who had gone out to execute the wise men of Babylon;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 15, 'he asked Arioch, the royal official, "Why is the decree of the king so urgent?" Arioch then explained the matter to Daniel.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 16, 'So Daniel went in and requested that the king give him time and he would tell the king the interpretation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 17, 'Then Daniel went to his home and informed his companions, Hananiah, Mishael, and Azariah,', 'en', 'NRSV-CE', 'God Reveals Nebuchadnezzar"s Dream'),
(27, 'Dan', 'Daniel', 2, 18, 'and told them to seek mercy from the God of heaven concerning this mystery, so that Daniel and his companions with the rest of the wise men of Babylon might not perish.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 19, 'Then the mystery was revealed to Daniel in a vision of the night, and Daniel blessed the God of heaven.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 20, 'Daniel said:  
"Blessed be the name of God from age to age,  
    for wisdom and power are his.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 21, 'He changes times and seasons,  
    deposes kings and sets up kings;  
he gives wisdom to the wise  
    and knowledge to those who have understanding.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 22, 'He reveals deep and hidden things;  
    he knows what is in the darkness,  
    and light dwells with him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 23, 'To you, O God of my ancestors,  
    I give thanks and praise,  
for you have given me wisdom and power,  
    and have now revealed to me what we asked of you,  
    for you have revealed to us what the king ordered."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 24, 'Therefore Daniel went to Arioch, whom the king had appointed to destroy the wise men of Babylon, and said to him, "Do not destroy the wise men of Babylon; bring me in before the king, and I will give the king the interpretation."', 'en', 'NRSV-CE', 'Daniel Interprets the Dream'),
(27, 'Dan', 'Daniel', 2, 25, 'Then Arioch quickly brought Daniel before the king and said to him: "I have found among the exiles from Judah a man who can tell the king the interpretation."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 26, 'The king said to Daniel, whose name was Belteshazzar, "Are you able to tell me the dream that I have seen and its interpretation?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 27, 'Daniel answered the king, "No wise men, enchanters, magicians, or diviners can show to the king the mystery that the king is asking,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 28, 'but there is a God in heaven who reveals mysteries, and he has disclosed to King Nebuchadnezzar what will happen at the end of days. Your dream and the visions of your head as you lay in bed were these:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 29, 'To you, O king, as you lay in bed, came thoughts of what would be hereafter, and the revealer of mysteries disclosed to you what is to be.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 30, 'But as for me, this mystery has not been revealed to me because of any wisdom that I have more than any other living being, but in order that the interpretation may be known to the king and that you may understand the thoughts of your mind.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 31, '"You were looking, O king, and lo! there was a great statue. This statue was huge, its brilliance extraordinary; it was standing before you, and its appearance was frightening.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 32, 'The head of that statue was of fine gold, its chest and arms of silver, its middle and thighs of bronze,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 33, 'its legs of iron, its feet partly of iron and partly of clay.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 34, 'As you looked on, a stone was cut out, not by human hands, and it struck the statue on its feet of iron and clay and broke them in pieces.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 35, 'Then the iron, the clay, the bronze, the silver, and the gold, were all broken in pieces and became like the chaff of the summer threshing floors; and the wind carried them away, so that not a trace of them could be found. But the stone that struck the statue became a great mountain and filled the whole earth.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 36, '"This was the dream; now we will tell the king its interpretation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 37, 'You, O king, the king of kings--to whom the God of heaven has given the kingdom, the power, the might, and the glory,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 38, 'into whose hand he has given human beings, wherever they live, the wild animals of the field, and the birds of the air, and whom he has established as ruler over them all--you are the head of gold.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 39, 'After you shall arise another kingdom inferior to yours, and yet a third kingdom of bronze, which shall rule over the whole earth.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 40, 'And there shall be a fourth kingdom, strong as iron; just as iron crushes and smashes everything, it shall crush and shatter all these.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 41, 'As you saw the feet and toes partly of potter"s clay and partly of iron, it shall be a divided kingdom; but some of the strength of iron shall be in it, as you saw the iron mixed with the clay.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 42, 'As the toes of the feet were part iron and part clay, so the kingdom shall be partly strong and partly brittle.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 43, 'As you saw the iron mixed with clay, so will they mix with one another in marriage, but they will not hold together, just as iron does not mix with clay.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 44, 'And in the days of those kings the God of heaven will set up a kingdom that shall never be destroyed, nor shall this kingdom be left to another people. It shall crush all these kingdoms and bring them to an end, and it shall stand forever;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 45, 'just as you saw that a stone was cut from the mountain not by hands, and that it crushed the iron, the bronze, the clay, the silver, and the gold. The great God has informed the king what shall be hereafter. The dream is certain, and its interpretation trustworthy."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 46, 'Then King Nebuchadnezzar fell on his face, worshiped Daniel, and commanded that a grain offering and incense be offered to him.', 'en', 'NRSV-CE', 'Daniel and His Friends Promoted'),
(27, 'Dan', 'Daniel', 2, 47, 'The king said to Daniel, "Truly, your God is God of gods and Lord of kings and a revealer of mysteries, for you have been able to reveal this mystery!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 48, 'Then the king promoted Daniel, gave him many great gifts, and made him ruler over the whole province of Babylon and chief prefect over all the wise men of Babylon.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 2, 49, 'Daniel made a request of the king, and he appointed Shadrach, Meshach, and Abednego over the affairs of the province of Babylon. But Daniel remained at the king"s court.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 3, 1, 'King Nebuchadnezzar made a golden statue whose height was sixty cubits and whose width was six cubits; he set it up on the plain of Dura in the province of Babylon.', 'en', 'NRSV-CE', 'The Golden Image'),
(27, 'Dan', 'Daniel', 3, 2, 'Then King Nebuchadnezzar sent for the satraps, the prefects, and the governors, the counselors, the treasurers, the justices, the magistrates, and all the officials of the provinces, to assemble and come to the dedication of the statue that King Nebuchadnezzar had set up.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 3, 'So the satraps, the prefects, and the governors, the counselors, the treasurers, the justices, the magistrates, and all the officials of the provinces, assembled for the dedication of the statue that King Nebuchadnezzar had set up. When they were standing before the statue that Nebuchadnezzar had set up,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 4, 'the herald proclaimed aloud, "You are commanded, O peoples, nations, and languages,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 5, 'that when you hear the sound of the horn, pipe, lyre, trigon, harp, drum, and entire musical ensemble, you are to fall down and worship the golden statue that King Nebuchadnezzar has set up.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 6, 'Whoever does not fall down and worship shall immediately be thrown into a furnace of blazing fire."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 7, 'Therefore, as soon as all the peoples heard the sound of the horn, pipe, lyre, trigon, harp, drum, and entire musical ensemble, all the peoples, nations, and languages fell down and worshiped the golden statue that King Nebuchadnezzar had set up.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 8, 'Accordingly, at this time certain Chaldeans came forward and denounced the Jews.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 9, 'They said to King Nebuchadnezzar, "O king, live forever!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 10, 'You, O king, have made a decree, that everyone who hears the sound of the horn, pipe, lyre, trigon, harp, drum, and entire musical ensemble, shall fall down and worship the golden statue,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 11, 'and whoever does not fall down and worship shall be thrown into a furnace of blazing fire.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 12, 'There are certain Jews whom you have appointed over the affairs of the province of Babylon: Shadrach, Meshach, and Abednego. These pay no heed to you, O king. They do not serve your gods and they do not worship the golden statue that you have set up."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 13, 'Then Nebuchadnezzar in furious rage commanded that Shadrach, Meshach, and Abednego be brought in; so they brought those men before the king.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 14, 'Nebuchadnezzar said to them, "Is it true, O Shadrach, Meshach, and Abednego, that you do not serve my gods and you do not worship the golden statue that I have set up?', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 15, 'Now if you are ready when you hear the sound of the horn, pipe, lyre, trigon, harp, drum, and entire musical ensemble to fall down and worship the statue that I have made, well and good. But if you do not worship, you shall immediately be thrown into a furnace of blazing fire, and who is the god that will deliver you out of my hands?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 16, 'Shadrach, Meshach, and Abednego answered the king, "O Nebuchadnezzar, we have no need to present a defense to you in this matter.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 17, 'If our God whom we serve is able to deliver us from the furnace of blazing fire and out of your hand, O king, let him deliver us.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 18, 'But if not, be it known to you, O king, that we will not serve your gods and we will not worship the golden statue that you have set up."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 19, 'Then Nebuchadnezzar was so filled with rage against Shadrach, Meshach, and Abednego that his face was distorted. He ordered the furnace heated up seven times more than was customary,', 'en', 'NRSV-CE', 'The Fiery Furnace'),
(27, 'Dan', 'Daniel', 3, 20, 'and ordered some of the strongest guards in his army to bind Shadrach, Meshach, and Abednego and to throw them into the furnace of blazing fire.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 21, 'So the men were bound, still wearing their tunics, their trousers, their hats, and their other garments, and they were thrown into the furnace of blazing fire.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 22, 'Because the king"s command was urgent and the furnace was so overheated, the raging flames killed the men who lifted Shadrach, Meshach, and Abednego.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 23, 'But the three men, Shadrach, Meshach, and Abednego, fell down, bound, into the furnace of blazing fire.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 24, 'They walked around in the midst of the flames, singing hymns to God and blessing the Lord.', 'en', 'NRSV-CE', 'The Prayer of Azariah in the Furnace'),
(27, 'Dan', 'Daniel', 3, 25, 'Then Azariah stood still in the fire and prayed aloud:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 26, '"Blessed are you, O Lord, God of our ancestors, and worthy of praise;  
    and glorious is your name forever!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 27, 'For you are just in all you have done;  
    all your works are true and your ways right,  
    and all your judgments are true.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 28, 'You have executed true judgments in all you have brought upon us  
    and upon Jerusalem, the holy city of our ancestors;  
    by a true judgment you have brought all this upon us because of our sins.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 29, 'For we have sinned and broken your law in turning away from you;  
    in all matters we have sinned grievously.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 30, 'We have not obeyed your commandments,  
    we have not kept them or done what you have commanded us for our own good.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 31, 'So all that you have brought upon us,  
    and all that you have done to us,  
    you have done by a true judgment.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 32, 'You have handed us over to our enemies, lawless and hateful rebels,  
    and to an unjust king, the most wicked in all the world.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 33, 'And now we cannot open our mouths;  
    we, your servants who worship you, have become a shame and a reproach.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 34, 'For your name"s sake do not give us up forever,  
    and do not annul your covenant.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 35, 'Do not withdraw your mercy from us,  
for the sake of Abraham your beloved  
    and for the sake of your servant Isaac  
    and Israel your holy one,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 36, 'to whom you promised  
    to multiply their descendants like the stars of heaven  
    and like the sand on the shore of the sea.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 37, 'For we, O Lord, have become fewer than any other nation,  
    and are brought low this day in all the world because of our sins.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 38, 'In our day we have no ruler, or prophet, or leader,  
    no burnt offering, or sacrifice, or oblation, or incense,  
    no place to make an offering before you and to find mercy.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 39, 'Yet with a contrite heart and a humble spirit may we be accepted,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 40, 'as though it were with burnt offerings of rams and bulls,  
    or with tens of thousands of fat lambs;  
    such may our sacrifice be in your sight today,  
    and may we unreservedly follow you,  
    for no shame will come to those who trust in you.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 41, 'And now with all our heart we follow you;  
    we fear you and seek your presence.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 42, 'Do not put us to shame,  
    but deal with us in your patience  
    and in your abundant mercy.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 43, 'Deliver us in accordance with your marvelous works,  
    and bring glory to your name, O Lord.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 44, 'Let all who do harm to your servants be put to shame;  
    let them be disgraced and deprived of all power,  
    and let their strength be broken.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 45, 'Let them know that you alone are the Lord God,  
    glorious over the whole world."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 46, 'Now the king"s servants who threw them in kept stoking the furnace with naphtha, pitch, tow, and brushwood.', 'en', 'NRSV-CE', 'The Song of the Three Jews'),
(27, 'Dan', 'Daniel', 3, 47, 'And the flames poured out above the furnace forty-nine cubits,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 48, 'and spread out and burned those Chaldeans who were caught near the furnace.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 49, 'But the angel of the Lord came down into the furnace to be with Azariah and his companions, and drove the fiery flame out of the furnace,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 50, 'and made the inside of the furnace as though a moist wind were whistling through it. The fire did not touch them at all and caused them no pain or distress.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 51, 'Then the three with one voice praised and glorified and blessed God in the furnace:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 52, '"Blessed are you, O Lord, God of our ancestors,  
    and to be praised and highly exalted forever;  
And blessed is your glorious, holy name,  
    and to be highly praised and highly exalted forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 53, 'Blessed are you in the temple of your holy glory,  
    and to be extolled and highly glorified forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 54, 'Blessed are you who look into the depths from your throne on the cherubim,  
    and to be praised and highly exalted forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 55, 'Blessed are you on the throne of your kingdom,  
    and to be extolled and highly exalted forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 56, 'Blessed are you in the firmament of heaven,  
    and to be sung and glorified forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 57, '"Bless the Lord, all you works of the Lord;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 58, 'Bless the Lord, you heavens;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 59, 'Bless the Lord, you angels of the Lord;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 60, 'Bless the Lord, all you waters above the heavens;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 61, 'Bless the Lord, all you powers of the Lord;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 62, 'Bless the Lord, sun and moon;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 63, 'Bless the Lord, stars of heaven;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 64, '"Bless the Lord, all rain and dew;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 65, 'Bless the Lord, all you winds;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 66, 'Bless the Lord, fire and heat;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 67, 'Bless the Lord, winter cold and summer heat;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 68, 'Bless the Lord, dews and falling snow;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 69, 'Bless the Lord, ice and cold;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 70, 'Bless the Lord, frosts and snows;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 71, 'Bless the Lord, nights and days;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 72, 'Bless the Lord, light and darkness;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 73, 'Bless the Lord, lightnings and clouds;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 74, '"Let the earth bless the Lord;  
    let it sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 75, 'Bless the Lord, mountains and hills;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 76, 'Bless the Lord, all that grows in the ground;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 77, 'Bless the Lord, you springs;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 78, 'Bless the Lord, seas and rivers;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 79, 'Bless the Lord, you whales and all that swim in the waters;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 80, 'Bless the Lord, all birds of the air;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 81, 'Bless the Lord, all wild animals and cattle;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 82, '"Bless the Lord, all people on earth;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 83, 'Bless the Lord, O Israel;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 84, 'Bless the Lord, you priests of the Lord;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 85, 'Bless the Lord, you servants of the Lord;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 86, 'Bless the Lord, spirits and souls of the righteous;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 87, 'Bless the Lord, you who are holy and humble in heart;  
    sing praise to him and highly exalt him forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 88, '"Bless the Lord, Hananiah, Azariah, and Mishael;  
    sing praise to him and highly exalt him forever.  
For he has rescued us from Hades and saved us from the power of death,  
    and delivered us from the midst of the burning fiery furnace;  
    from the midst of the fire he has delivered us.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 89, 'Give thanks to the Lord, for he is good,  
    for his mercy endures forever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 90, 'All who worship the Lord, bless the God of gods,  
    sing praise to him and give thanks to him,  
    for his mercy endures forever."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 91, 'Hearing them sing, and amazed at seeing them alive, King Nebuchadnezzar rose up quickly. He said to his counselors, "Was it not three men that we threw bound into the fire?" They answered the king, "True, O king."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 92, 'He replied, "But I see four men unbound, walking in the middle of the fire, and they are not hurt; and the fourth has the appearance of a god."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 93, 'Nebuchadnezzar then approached the door of the furnace of blazing fire and said, "Shadrach, Meshach, and Abednego, servants of the Most High God, come out! Come here!" So Shadrach, Meshach, and Abednego came out from the fire.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 94, 'And the satraps, the prefects, the governors, and the king"s counselors gathered together and saw that the fire had not had any power over the bodies of those men; the hair of their heads was not singed, their tunics were not harmed, and not even the smell of fire came from them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 95, 'Nebuchadnezzar said, "Blessed be the God of Shadrach, Meshach, and Abednego, who has sent his angel and delivered his servants who trusted in him. They disobeyed the king"s command and yielded up their bodies rather than serve and worship any god except their own God.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 96, 'Therefore I make a decree: Any people, nation, or language that utters blasphemy against the God of Shadrach, Meshach, and Abednego shall be torn limb from limb, and their houses laid in ruins; for there is no other god who is able to deliver in this way."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 3, 97, 'Then the king promoted Shadrach, Meshach, and Abednego in the province of Babylon.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 4, 1, 'King Nebuchadnezzar to all peoples, nations, and languages that live throughout the earth: May you have abundant prosperity!', 'en', 'NRSV-CE', 'Nebuchadnezzar"s Second Dream'),
(27, 'Dan', 'Daniel', 4, 2, 'The signs and wonders that the Most High God has worked for me I am pleased to recount.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 3, 'How great are his signs,  
    how mighty his wonders!  
His kingdom is an everlasting kingdom,  
    and his sovereignty is from generation to generation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 4, 'I, Nebuchadnezzar, was living at ease in my home and prospering in my palace.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 5, 'I saw a dream that frightened me; my fantasies in bed and the visions of my head terrified me.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 6, 'So I made a decree that all the wise men of Babylon should be brought before me, in order that they might tell me the interpretation of the dream.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 7, 'Then the magicians, the enchanters, the Chaldeans, and the diviners came in, and I told them the dream, but they could not tell me its interpretation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 8, 'At last Daniel came in before me--he who was named Belteshazzar after the name of my god, and who is endowed with a spirit of the holy gods--and I told him the dream:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 9, '"O Belteshazzar, chief of the magicians, I know that you are endowed with a spirit of the holy gods and that no mystery is too difficult for you. Hear the dream that I saw; tell me its interpretation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 10, 'Upon my bed this is what I saw;  
    there was a tree at the center of the earth,  
    and its height was great.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 11, 'The tree grew great and strong,  
    its top reached to heaven,  
    and it was visible to the ends of the whole earth.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 12, 'Its foliage was beautiful,  
    its fruit abundant,  
    and it provided food for all.  
The animals of the field found shade under it,  
    the birds of the air nested in its branches,  
    and from it all living beings were fed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 13, '"I continued looking, in the visions of my head as I lay in bed, and there was a holy watcher, coming down from heaven.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 14, 'He cried aloud and said:
"Cut down the tree and chop off its branches,  
    strip off its foliage and scatter its fruit.  
Let the animals flee from beneath it  
    and the birds from its branches.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 15, 'But leave its stump and roots in the ground,  
    with a band of iron and bronze,  
    in the tender grass of the field.  
Let him be bathed with the dew of heaven,  
    and let his lot be with the animals of the field  
    in the grass of the earth.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 16, 'Let his mind be changed from that of a human,  
    and let the mind of an animal be given to him.  
    And let seven times pass over him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 17, 'The sentence is rendered by decree of the watchers,  
    the decision is given by order of the holy ones,  
in order that all who live may know  
    that the Most High is sovereign over the kingdom of mortals;  
he gives it to whom he will  
    and sets over it the lowliest of human beings."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 18, '"This is the dream that I, King Nebuchadnezzar, saw. Now you, Belteshazzar, declare the interpretation, since all the wise men of my kingdom are unable to tell me the interpretation. You are able, however, for you are endowed with a spirit of the holy gods."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 19, 'Then Daniel, who was called Belteshazzar, was severely distressed for a while. His thoughts terrified him. The king said, "Belteshazzar, do not let the dream or the interpretation terrify you." Belteshazzar answered, "My lord, may the dream be for those who hate you, and its interpretation for your enemies!', 'en', 'NRSV-CE', 'Daniel Interprets the Second Dream'),
(27, 'Dan', 'Daniel', 4, 20, 'The tree that you saw, which grew great and strong, so that its top reached to heaven and was visible to the end of the whole earth,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 21, 'whose foliage was beautiful and its fruit abundant, and which provided food for all, under which animals of the field lived, and in whose branches the birds of the air had nests--', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 22, 'it is you, O king! You have grown great and strong. Your greatness has increased and reaches to heaven, and your sovereignty to the ends of the earth.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 23, 'And whereas the king saw a holy watcher coming down from heaven and saying, "Cut down the tree and destroy it, but leave its stump and roots in the ground, with a band of iron and bronze, in the grass of the field; and let him be bathed with the dew of heaven, and let his lot be with the animals of the field, until seven times pass over him"--', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 24, 'this is the interpretation, O king, and it is a decree of the Most High that has come upon my lord the king:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 25, 'You shall be driven away from human society, and your dwelling shall be with the wild animals. You shall be made to eat grass like oxen, you shall be bathed with the dew of heaven, and seven times shall pass over you, until you have learned that the Most High has sovereignty over the kingdom of mortals, and gives it to whom he will.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 26, 'As it was commanded to leave the stump and roots of the tree, your kingdom shall be re-established for you from the time that you learn that Heaven is sovereign.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 27, 'Therefore, O king, may my counsel be acceptable to you: atone for your sins with righteousness, and your iniquities with mercy to the oppressed, so that your prosperity may be prolonged."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 28, 'All this came upon King Nebuchadnezzar.', 'en', 'NRSV-CE', 'Nebuchadnezzar"s Humiliation'),
(27, 'Dan', 'Daniel', 4, 29, 'At the end of twelve months he was walking on the roof of the royal palace of Babylon,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 30, 'and the king said, "Is this not magnificent Babylon, which I have built as a royal capital by my mighty power and for my glorious majesty?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 31, 'While the words were still in the king"s mouth, a voice came from heaven: "O King Nebuchadnezzar, to you it is declared: The kingdom has departed from you!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 32, 'You shall be driven away from human society, and your dwelling shall be with the animals of the field. You shall be made to eat grass like oxen, and seven times shall pass over you, until you have learned that the Most High has sovereignty over the kingdom of mortals and gives it to whom he will."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 33, 'Immediately the sentence was fulfilled against Nebuchadnezzar. He was driven away from human society, ate grass like oxen, and his body was bathed with the dew of heaven, until his hair grew as long as eagles" feathers and his nails became like birds" claws.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 34, 'When that period was over, I, Nebuchadnezzar, lifted my eyes to heaven, and my reason returned to me.
I blessed the Most High,  
    and praised and honored the one who lives forever.  
For his sovereignty is an everlasting sovereignty,  
    and his kingdom endures from generation to generation.', 'en', 'NRSV-CE', 'Nebuchadnezzar Praises God'),
(27, 'Dan', 'Daniel', 4, 35, 'All the inhabitants of the earth are accounted as nothing,  
    and he does what he wills with the host of heaven  
    and the inhabitants of the earth.  
There is no one who can stay his hand  
    or say to him, "What are you doing?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 36, 'At that time my reason returned to me; and my majesty and splendor were restored to me for the glory of my kingdom. My counselors and my lords sought me out, I was re-established over my kingdom, and still more greatness was added to me.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 4, 37, 'Now I, Nebuchadnezzar, praise and extol and honor the King of heaven,
for all his works are truth,  
    and his ways are justice;  
and he is able to bring low  
    those who walk in pride.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 5, 1, 'King Belshazzar made a great festival for a thousand of his lords, and he was drinking wine in the presence of the thousand.', 'en', 'NRSV-CE', 'Belshazzar"s Feast'),
(27, 'Dan', 'Daniel', 5, 2, 'Under the influence of the wine, Belshazzar commanded that they bring in the vessels of gold and silver that his father Nebuchadnezzar had taken out of the temple in Jerusalem, so that the king and his lords, his wives, and his concubines might drink from them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 3, 'So they brought in the vessels of gold and silver that had been taken out of the temple, the house of God in Jerusalem, and the king and his lords, his wives, and his concubines drank from them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 4, 'They drank the wine and praised the gods of gold and silver, bronze, iron, wood, and stone.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 5, 'Immediately the fingers of a human hand appeared and began writing on the plaster of the wall of the royal palace, next to the lampstand. The king was watching the hand as it wrote.', 'en', 'NRSV-CE', 'The Writing on the Wall'),
(27, 'Dan', 'Daniel', 5, 6, 'Then the king"s face turned pale, and his thoughts terrified him. His limbs gave way, and his knees knocked together.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 7, 'The king cried aloud to bring in the enchanters, the Chaldeans, and the diviners; and the king said to the wise men of Babylon, "Whoever can read this writing and tell me its interpretation shall be clothed in purple, have a chain of gold around his neck, and rank third in the kingdom."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 8, 'Then all the king"s wise men came in, but they could not read the writing or tell the king the interpretation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 9, 'Then King Belshazzar became greatly terrified and his face turned pale, and his lords were perplexed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 10, 'The queen, when she heard the discussion of the king and his lords, came into the banqueting hall. The queen said, "O king, live forever! Do not let your thoughts terrify you or your face grow pale.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 11, 'There is a man in your kingdom who is endowed with a spirit of the holy gods. In the days of your father he was found to have enlightenment, understanding, and wisdom like the wisdom of the gods. Your father, King Nebuchadnezzar, made him chief of the magicians, enchanters, Chaldeans, and diviners,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 12, 'because an excellent spirit, knowledge, and understanding to interpret dreams, explain riddles, and solve problems were found in this Daniel, whom the king named Belteshazzar. Now let Daniel be called, and he will give the interpretation."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 13, 'Then Daniel was brought in before the king. The king said to Daniel, "So you are Daniel, one of the exiles of Judah, whom my father the king brought from Judah?', 'en', 'NRSV-CE', 'The Writing on the Wall Interpreted'),
(27, 'Dan', 'Daniel', 5, 14, 'I have heard of you that a spirit of the gods is in you, and that enlightenment, understanding, and excellent wisdom are found in you.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 15, 'Now the wise men, the enchanters, have been brought in before me to read this writing and tell me its interpretation, but they were not able to give the interpretation of the matter.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 16, 'But I have heard that you can give interpretations and solve problems. Now if you are able to read the writing and tell me its interpretation, you shall be clothed in purple, have a chain of gold around your neck, and rank third in the kingdom."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 17, 'Then Daniel answered in the presence of the king, "Let your gifts be for yourself, or give your rewards to someone else! Nevertheless I will read the writing to the king and let him know the interpretation.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 18, 'O king, the Most High God gave your father Nebuchadnezzar kingship, greatness, glory, and majesty.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 19, 'And because of the greatness that he gave him, all peoples, nations, and languages trembled and feared before him. He killed those he wanted to kill, kept alive those he wanted to keep alive, honored those he wanted to honor, and degraded those he wanted to degrade.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 20, 'But when his heart was lifted up and his spirit was hardened so that he acted proudly, he was deposed from his kingly throne, and his glory was stripped from him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 21, 'He was driven from human society, and his mind was made like that of an animal. His dwelling was with the wild asses, he was fed grass like oxen, and his body was bathed with the dew of heaven, until he learned that the Most High God has sovereignty over the kingdom of mortals, and sets over it whomever he will.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 22, 'And you, Belshazzar his son, have not humbled your heart, even though you knew all this!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 23, 'You have exalted yourself against the Lord of heaven! The vessels of his temple have been brought in before you, and you and your lords, your wives and your concubines have been drinking wine from them. You have praised the gods of silver and gold, of bronze, iron, wood, and stone, which do not see or hear or know; but the God in whose power is your very breath, and to whom belong all your ways, you have not honored.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 24, '"So from his presence the hand was sent and this writing was inscribed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 25, 'And this is the writing that was inscribed: mene, mene, tekel, and parsin.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 26, 'This is the interpretation of the matter: mene, God has numbered the days of your kingdom and brought it to an end;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 27, 'tekel, you have been weighed on the scales and found wanting;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 28, 'peres, your kingdom is divided and given to the Medes and Persians."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 29, 'Then Belshazzar gave the command, and Daniel was clothed in purple, a chain of gold was put around his neck, and a proclamation was made concerning him that he should rank third in the kingdom.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 30, 'That very night Belshazzar, the Chaldean king, was killed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 5, 31, 'And Darius the Mede received the kingdom, being about sixty-two years old.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 6, 1, 'It pleased Darius to set over the kingdom one hundred twenty satraps, stationed throughout the whole kingdom,', 'en', 'NRSV-CE', 'The Plot against Daniel'),
(27, 'Dan', 'Daniel', 6, 2, 'and over them three presidents, including Daniel; to these the satraps gave account, so that the king might suffer no loss.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 3, 'Soon Daniel distinguished himself above all the other presidents and satraps because an excellent spirit was in him, and the king planned to appoint him over the whole kingdom.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 4, 'So the presidents and the satraps tried to find grounds for complaint against Daniel in connection with the kingdom. But they could find no grounds for complaint or any corruption, because he was faithful, and no negligence or corruption could be found in him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 5, 'The men said, "We shall not find any ground for complaint against this Daniel unless we find it in connection with the law of his God."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 6, 'So the presidents and satraps conspired and came to the king and said to him, "O King Darius, live forever!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 7, 'All the presidents of the kingdom, the prefects and the satraps, the counselors and the governors are agreed that the king should establish an ordinance and enforce an interdict, that whoever prays to anyone, divine or human, for thirty days, except to you, O king, shall be thrown into a den of lions.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 8, 'Now, O king, establish the interdict and sign the document, so that it cannot be changed, according to the law of the Medes and the Persians, which cannot be revoked."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 9, 'Therefore King Darius signed the document and interdict.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 10, 'Although Daniel knew that the document had been signed, he continued to go to his house, which had windows in its upper room open toward Jerusalem, and to get down on his knees three times a day to pray to his God and praise him, just as he had done previously.', 'en', 'NRSV-CE', 'Daniel in the Lions" Den'),
(27, 'Dan', 'Daniel', 6, 11, 'The conspirators came and found Daniel praying and seeking mercy before his God.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 12, 'Then they approached the king and said concerning the interdict, "O king! Did you not sign an interdict, that anyone who prays to anyone, divine or human, within thirty days except to you, O king, shall be thrown into a den of lions?" The king answered, "The thing stands fast, according to the law of the Medes and Persians, which cannot be revoked."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 13, 'Then they responded to the king, "Daniel, one of the exiles from Judah, pays no attention to you, O king, or to the interdict you have signed, but he is saying his prayers three times a day."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 14, 'When the king heard the charge, he was very much distressed. He was determined to save Daniel, and until the sun went down he made every effort to rescue him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 15, 'Then the conspirators came to the king and said to him, "Know, O king, that it is a law of the Medes and Persians that no interdict or ordinance that the king establishes can be changed."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 16, 'Then the king gave the command, and Daniel was brought and thrown into the den of lions. The king said to Daniel, "May your God, whom you faithfully serve, deliver you!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 17, 'A stone was brought and laid on the mouth of the den, and the king sealed it with his own signet and with the signet of his lords, so that nothing might be changed concerning Daniel.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 18, 'Then the king went to his palace and spent the night fasting; no food was brought to him, and sleep fled from him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 19, 'Then, at break of day, the king got up and hurried to the den of lions.', 'en', 'NRSV-CE', 'Daniel Saved from the Lions'),
(27, 'Dan', 'Daniel', 6, 20, 'When he came near the den where Daniel was, he cried out anxiously to Daniel, "O Daniel, servant of the living God, has your God whom you faithfully serve been able to deliver you from the lions?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 21, 'Daniel then said to the king, "O king, live forever!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 22, 'My God sent his angel and shut the lions" mouths so that they would not hurt me, because I was found blameless before him; and also before you, O king, I have done no wrong."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 23, 'Then the king was exceedingly glad and commanded that Daniel be taken up out of the den. So Daniel was taken up out of the den, and no kind of harm was found on him, because he had trusted in his God.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 24, 'The king gave a command, and those who had accused Daniel were brought and thrown into the den of lions--they, their children, and their wives. Before they reached the bottom of the den the lions overpowered them and broke all their bones in pieces.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 25, 'Then King Darius wrote to all peoples and nations of every language throughout the whole world: "May you have abundant prosperity!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 26, 'I make a decree, that in all my royal dominion people should tremble and fear before the God of Daniel:
For he is the living God,  
    enduring forever.  
His kingdom shall never be destroyed,  
    and his dominion has no end.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 27, 'He delivers and rescues,  
    he works signs and wonders in heaven and on earth;  
for he has saved Daniel  
    from the power of the lions."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 6, 28, 'So this Daniel prospered during the reign of Darius and the reign of Cyrus the Persian.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 7, 1, 'In the first year of King Belshazzar of Babylon, Daniel had a dream and visions of his head as he lay in bed. Then he wrote down the dream:', 'en', 'NRSV-CE', 'Visions of the Four Beasts'),
(27, 'Dan', 'Daniel', 7, 2, 'I, Daniel, saw in my vision by night the four winds of heaven stirring up the great sea,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 3, 'and four great beasts came up out of the sea, different from one another.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 4, 'The first was like a lion and had eagles" wings. Then, as I watched, its wings were plucked off, and it was lifted up from the ground and made to stand on two feet like a human being; and a human mind was given to it.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 5, 'Another beast appeared, a second one, that looked like a bear. It was raised up on one side, had three tusks in its mouth among its teeth and was told, "Arise, devour many bodies!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 6, 'After this, as I watched, another appeared, like a leopard. The beast had four wings of a bird on its back and four heads; and dominion was given to it.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 7, 'After this I saw in the visions by night a fourth beast, terrifying and dreadful and exceedingly strong. It had great iron teeth and was devouring, breaking in pieces, and stamping what was left with its feet. It was different from all the beasts that preceded it, and it had ten horns.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 8, 'I was considering the horns, when another horn appeared, a little one coming up among them; to make room for it, three of the earlier horns were plucked up by the roots. There were eyes like human eyes in this horn, and a mouth speaking arrogantly.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 9, 'As I watched,  
thrones were set in place,  
    and an Ancient One took his throne,  
his clothing was white as snow,  
    and the hair of his head like pure wool;  
his throne was fiery flames,  
    and its wheels were burning fire.', 'en', 'NRSV-CE', 'Judgment before the Ancient One'),
(27, 'Dan', 'Daniel', 7, 10, 'A stream of fire issued  
    and flowed out from his presence.  
A thousand thousands served him,  
    and ten thousand times ten thousand stood attending him.  
The court sat in judgment,  
    and the books were opened.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 11, 'I watched then because of the noise of the arrogant words that the horn was speaking. And as I watched, the beast was put to death, and its body destroyed and given over to be burned with fire.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 12, 'As for the rest of the beasts, their dominion was taken away, but their lives were prolonged for a season and a time.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 13, 'As I watched in the night visions,
I saw one like a human being  
    coming with the clouds of heaven.  
And he came to the Ancient One  
    and was presented before him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 14, 'To him was given dominion  
    and glory and kingship,  
that all peoples, nations, and languages  
    should serve him.  
His dominion is an everlasting dominion  
    that shall not pass away,  
and his kingship is one  
    that shall never be destroyed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 15, 'As for me, Daniel, my spirit was troubled within me, and the visions of my head terrified me.', 'en', 'NRSV-CE', 'Daniel"s Visions Interpreted'),
(27, 'Dan', 'Daniel', 7, 16, 'I approached one of the attendants to ask him the truth concerning all this. So he said that he would disclose to me the interpretation of the matter:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 17, '"As for these four great beasts, four kings shall arise out of the earth.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 18, 'But the holy ones of the Most High shall receive the kingdom and possess the kingdom forever--forever and ever."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 19, 'Then I desired to know the truth concerning the fourth beast, which was different from all the rest, exceedingly terrifying, with its teeth of iron and claws of bronze, and which devoured and broke in pieces, and stamped what was left with its feet;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 20, 'and concerning the ten horns that were on its head, and concerning the other horn, which came up and to make room for which three of them fell out--the horn that had eyes and a mouth that spoke arrogantly, and that seemed greater than the others.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 21, 'As I looked, this horn made war with the holy ones and was prevailing over them,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 22, 'until the Ancient One came; then judgment was given for the holy ones of the Most High, and the time arrived when the holy ones gained possession of the kingdom.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 23, 'This is what he said: "As for the fourth beast,
there shall be a fourth kingdom on earth  
    that shall be different from all the other kingdoms;  
it shall devour the whole earth,  
    and trample it down, and break it to pieces.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 24, 'As for the ten horns,  
out of this kingdom ten kings shall arise,  
    and another shall arise after them.  
This one shall be different from the former ones,  
    and shall put down three kings.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 25, 'He shall speak words against the Most High,  
    shall wear out the holy ones of the Most High,  
    and shall attempt to change the sacred seasons and the law;  
and they shall be given into his power  
    for a time, two times, and half a time.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 26, 'Then the court shall sit in judgment,  
    and his dominion shall be taken away,  
    to be consumed and totally destroyed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 27, 'The kingship and dominion  
    and the greatness of the kingdoms under the whole heaven  
    shall be given to the people of the holy ones of the Most High;  
their kingdom shall be an everlasting kingdom,  
    and all dominions shall serve and obey them."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 7, 28, 'Here the account ends. As for me, Daniel, my thoughts greatly terrified me, and my face turned pale; but I kept the matter in my mind.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 8, 1, 'In the third year of the reign of King Belshazzar a vision appeared to me, Daniel, after the one that had appeared to me at first.', 'en', 'NRSV-CE', 'Vision of a Ram and a Goat'),
(27, 'Dan', 'Daniel', 8, 2, 'In the vision I was looking and saw myself in Susa the capital, in the province of Elam, and I was by the river Ulai.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 3, 'I looked up and saw a ram standing beside the river. It had two horns. Both horns were long, but one was longer than the other, and the longer one came up second.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 4, 'I saw the ram charging westward and northward and southward. All beasts were powerless to withstand it, and no one could rescue from its power; it did as it pleased and became strong.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 5, 'As I was watching, a male goat appeared from the west, coming across the face of the whole earth without touching the ground. The goat had a horn between its eyes.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 6, 'It came toward the ram with the two horns that I had seen standing beside the river, and it ran at it with savage force.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 7, 'I saw it approaching the ram. It was enraged against it and struck the ram, breaking its two horns. The ram did not have power to withstand it; it threw the ram down to the ground and trampled upon it, and there was no one who could rescue the ram from its power.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 8, 'Then the male goat grew exceedingly great; but at the height of its power, the great horn was broken, and in its place there came up four prominent horns toward the four winds of heaven.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 9, 'Out of one of them came another horn, a little one, which grew exceedingly great toward the south, toward the east, and toward the beautiful land.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 10, 'It grew as high as the host of heaven. It threw down to the earth some of the host and some of the stars, and trampled on them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 11, 'Even against the prince of the host it acted arrogantly; it took the regular burnt offering away from him and overthrew the place of his sanctuary.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 12, 'Because of wickedness, the host was given over to it together with the regular burnt offering; it cast truth to the ground, and kept prospering in what it did.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 13, 'Then I heard a holy one speaking, and another holy one said to the one that spoke, "For how long is this vision concerning the regular burnt offering, the transgression that makes desolate, and the giving over of the sanctuary and host to be trampled?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 14, 'And he answered him, "For two thousand three hundred evenings and mornings; then the sanctuary shall be restored to its rightful state."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 15, 'When I, Daniel, had seen the vision, I tried to understand it. Then someone appeared standing before me, having the appearance of a man,', 'en', 'NRSV-CE', 'Gabriel Interprets the Vision'),
(27, 'Dan', 'Daniel', 8, 16, 'and I heard a human voice by the Ulai, calling, "Gabriel, help this man understand the vision."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 17, 'So he came near where I stood; and when he came, I became frightened and fell prostrate. But he said to me, "Understand, O mortal, that the vision is for the time of the end."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 18, 'As he was speaking to me, I fell into a trance, face to the ground; then he touched me and set me on my feet.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 19, 'He said, "Listen, and I will tell you what will take place later in the period of wrath; for it refers to the appointed time of the end.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 20, 'As for the ram that you saw with the two horns, these are the kings of Media and Persia.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 21, 'The male goat is the king of Greece, and the great horn between its eyes is the first king.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 22, 'As for the horn that was broken, in place of which four others arose, four kingdoms shall arise from his nation, but not with his power.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 23, 'At the end of their rule,  
    when the transgressions have reached their full measure,  
a king of bold countenance shall arise,  
    skilled in intrigue.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 24, 'He shall grow strong in power,  
    shall cause fearful destruction,  
    and shall succeed in what he does.  
He shall destroy the powerful  
    and the people of the holy ones.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 25, 'By his cunning  
    he shall make deceit prosper under his hand,  
    and in his own mind he shall be great.  
Without warning he shall destroy many  
    and shall even rise up against the Prince of princes.  
But he shall be broken, and not by human hands.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 26, 'The vision of the evenings and the mornings that has been told is true. As for you, seal up the vision, for it refers to many days from now."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 8, 27, 'So I, Daniel, was overcome and lay sick for some days; then I arose and went about the king"s business. But I was dismayed by the vision and did not understand it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 9, 1, 'In the first year of Darius son of Ahasuerus, by birth a Mede, who became king over the realm of the Chaldeans--', 'en', 'NRSV-CE', 'Daniel"s Prayer for the People'),
(27, 'Dan', 'Daniel', 9, 2, 'in the first year of his reign, I, Daniel, perceived in the books the number of years that, according to the word of the LORD to the prophet Jeremiah, must be fulfilled for the devastation of Jerusalem, namely, seventy years.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 3, 'Then I turned to the Lord God, to seek an answer by prayer and supplication with fasting and sackcloth and ashes.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 4, 'I prayed to the LORD my God and made confession, saying,
"Ah, Lord, great and awesome God, keeping covenant and steadfast love with those who love you and keep your commandments,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 5, 'we have sinned and done wrong, acted wickedly and rebelled, turning aside from your commandments and ordinances.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 6, 'We have not listened to your servants the prophets, who spoke in your name to our kings, our princes, and our ancestors, and to all the people of the land.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 7, '"Righteousness is on your side, O Lord, but open shame, as at this day, falls on us, the people of Judah, the inhabitants of Jerusalem, and all Israel, those who are near and those who are far away, in all the lands to which you have driven them, because of the treachery that they have committed against you.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 8, 'Open shame, O LORD, falls on us, our kings, our officials, and our ancestors, because we have sinned against you.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 9, 'To the Lord our God belong mercy and forgiveness, for we have rebelled against him,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 10, 'and have not obeyed the voice of the LORD our God by following his laws, which he set before us by his servants the prophets.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 11, '"All Israel has transgressed your law and turned aside, refusing to obey your voice. So the curse and the oath written in the law of Moses, the servant of God, have been poured out upon us, because we have sinned against you.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 12, 'He has confirmed his words, which he spoke against us and against our rulers, by bringing upon us a calamity so great that what has been done against Jerusalem has never before been done under the whole heaven.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 13, 'Just as it is written in the law of Moses, all this calamity has come upon us. We did not entreat the favor of the LORD our God, turning from our iniquities and reflecting on his fidelity.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 14, 'So the LORD kept watch over this calamity until he brought it upon us. Indeed, the LORD our God is right in all that he has done; for we have disobeyed his voice.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 15, '"And now, O Lord our God, who brought your people out of the land of Egypt with a mighty hand and made your name renowned even to this day--we have sinned, we have done wickedly.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 16, 'O Lord, in view of all your righteous acts, let your anger and wrath, we pray, turn away from your city Jerusalem, your holy mountain; because of our sins and the iniquities of our ancestors, Jerusalem and your people have become a disgrace among all our neighbors.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 17, 'Now therefore, O our God, listen to the prayer of your servant and to his supplication, and for your own sake, Lord, let your face shine upon your desolated sanctuary.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 18, 'Incline your ear, O my God, and hear. Open your eyes and look at our desolation and the city that bears your name. We do not present our supplication before you on the ground of our righteousness, but on the ground of your great mercies.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 19, 'O Lord, hear; O Lord, forgive; O Lord, listen and act and do not delay! For your own sake, O my God, because your city and your people bear your name!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 20, 'While I was speaking, and was praying and confessing my sin and the sin of my people Israel, and presenting my supplication before the LORD my God on behalf of the holy mountain of my God--', 'en', 'NRSV-CE', 'The Seventy Weeks'),
(27, 'Dan', 'Daniel', 9, 21, 'while I was speaking in prayer, the man Gabriel, whom I had seen before in a vision, came to me in swift flight at the time of the evening sacrifice.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 22, 'He came and said to me, "Daniel, I have now come out to give you wisdom and understanding.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 23, 'At the beginning of your supplications a word went out, and I have come to declare it, for you are greatly beloved. So consider the word and understand the vision:', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 24, '"Seventy weeks are decreed for your people and your holy city: to finish the transgression, to put an end to sin, and to atone for iniquity, to bring in everlasting righteousness, to seal both vision and prophet, and to anoint a most holy place.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 25, 'Know therefore and understand: from the time that the word went out to restore and rebuild Jerusalem until the time of an anointed prince, there shall be seven weeks; and for sixty-two weeks it shall be built again with streets and moat, but in a troubled time.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 26, 'After the sixty-two weeks, an anointed one shall be cut off and shall have nothing, and the troops of the prince who is to come shall destroy the city and the sanctuary. Its end shall come with a flood, and to the end there shall be war. Desolations are decreed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 9, 27, 'He shall make a strong covenant with many for one week, and for half of the week he shall make sacrifice and offering cease; and in their place shall be an abomination that desolates, until the decreed end is poured out upon the desolator."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 10, 1, 'In the third year of King Cyrus of Persia a word was revealed to Daniel, who was named Belteshazzar. The word was true, and it concerned a great conflict. He understood the word, having received understanding in the vision.', 'en', 'NRSV-CE', 'Conflict of Nations and Heavenly Powers'),
(27, 'Dan', 'Daniel', 10, 2, 'At that time I, Daniel, had been mourning for three weeks.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 3, 'I had eaten no rich food, no meat or wine had entered my mouth, and I had not anointed myself at all, for the full three weeks.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 4, 'On the twenty-fourth day of the first month, as I was standing on the bank of the great river (that is, the Tigris),', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 5, 'I looked up and saw a man clothed in linen, with a belt of gold from Uphaz around his waist.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 6, 'His body was like beryl, his face like lightning, his eyes like flaming torches, his arms and legs like the gleam of burnished bronze, and the sound of his words like the roar of a multitude.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 7, 'I, Daniel, alone saw the vision; the people who were with me did not see the vision, though a great trembling fell upon them, and they fled and hid themselves.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 8, 'So I was left alone to see this great vision. My strength left me, and my complexion grew deathly pale, and I retained no strength.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 9, 'Then I heard the sound of his words; and when I heard the sound of his words, I fell into a trance, face to the ground.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 10, 'But then a hand touched me and roused me to my hands and knees.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 11, 'He said to me, "Daniel, greatly beloved, pay attention to the words that I am going to speak to you. Stand on your feet, for I have now been sent to you." So while he was speaking this word to me, I stood up trembling.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 12, 'He said to me, "Do not fear, Daniel, for from the first day that you set your mind to gain understanding and to humble yourself before your God, your words have been heard, and I have come because of your words.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 13, 'But the prince of the kingdom of Persia opposed me twenty-one days. So Michael, one of the chief princes, came to help me, and I left him there with the prince of the kingdom of Persia,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 14, 'and have come to help you understand what is to happen to your people at the end of days. For there is a further vision for those days."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 15, 'While he was speaking these words to me, I turned my face toward the ground and was speechless.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 16, 'Then one in human form touched my lips, and I opened my mouth to speak, and said to the one who stood before me, "My lord, because of the vision such pains have come upon me that I retain no strength.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 17, 'How can my lord"s servant talk with my lord? For I am shaking, no strength remains in me, and no breath is left in me."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 18, 'Again one in human form touched me and strengthened me.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 19, 'He said, "Do not fear, greatly beloved, you are safe. Be strong and courageous!" When he spoke to me, I was strengthened and said, "Let my lord speak, for you have strengthened me."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 20, 'Then he said, "Do you know why I have come to you? Now I must return to fight against the prince of Persia, and when I am through with him, the prince of Greece will come.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 10, 21, 'But I am to tell you what is inscribed in the book of truth. There is no one with me who contends against these princes except Michael, your prince.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 11, 1, 'As for me, in the first year of Darius the Mede, I stood up to support and strengthen him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 2, '"Now I will announce the truth to you. Three more kings shall arise in Persia. The fourth shall be far richer than all of them, and when he has become strong through his riches, he shall stir up all against the kingdom of Greece.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 3, 'Then a warrior king shall arise, who shall rule with great dominion and take action as he pleases.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 4, 'And while still rising in power, his kingdom shall be broken and divided toward the four winds of heaven, but not to his posterity, nor according to the dominion with which he ruled; for his kingdom shall be uprooted and go to others besides these.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 5, '"Then the king of the south shall grow strong, but one of his officers shall grow stronger than he and shall rule a realm greater than his own realm.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 6, 'After some years they shall make an alliance, and the daughter of the king of the south shall come to the king of the north to ratify the agreement. But she shall not retain her power, and his offspring shall not endure. She shall be given up, she and her attendants and her child and the one who supported her.
"In those times', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 7, 'a branch from her roots shall rise up in his place. He shall come against the army and enter the fortress of the king of the north, and he shall take action against them and prevail.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 8, 'Even their gods, with their idols and with their precious vessels of silver and gold, he shall carry off to Egypt as spoils of war. For some years he shall refrain from attacking the king of the north;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 9, 'then the latter shall invade the realm of the king of the south, but will return to his own land.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 10, '"His sons shall wage war and assemble a multitude of great forces, which shall advance like a flood and pass through, and again shall carry the war as far as his fortress.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 11, 'Moved with rage, the king of the south shall go out and do battle against the king of the north, who shall muster a great multitude, which shall, however, be defeated by his enemy.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 12, 'When the multitude has been carried off, his heart shall be exalted, and he shall overthrow tens of thousands, but he shall not prevail.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 13, 'For the king of the north shall again raise a multitude, larger than the former, and after some years he shall advance with a great army and abundant supplies.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 14, '"In those times many shall rise against the king of the south. The lawless among your own people shall lift themselves up in order to fulfill the vision, but they shall fail.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 15, 'Then the king of the north shall come and throw up siegeworks, and take a well-fortified city. And the forces of the south shall not stand, not even his picked troops, for there shall be no strength to resist.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 16, 'But he who comes against him shall take the actions he pleases, and no one shall withstand him. He shall take a position in the beautiful land, and all of it shall be in his power.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 17, 'He shall set his mind to come with the strength of his whole kingdom, and he shall bring terms of peace and perform them. In order to destroy the kingdom, he shall give him a woman in marriage; but it shall not succeed or be to his advantage.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 18, 'Afterward he shall turn to the coastlands, and shall capture many. But a commander shall put an end to his insolence; indeed, he shall turn his insolence back upon him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 19, 'Then he shall turn back toward the fortresses of his own land, but he shall stumble and fall, and shall not be found.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 20, '"Then shall arise in his place one who shall send an official for the glory of the kingdom; but within a few days he shall be broken, though not in anger or in battle.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 21, 'In his place shall arise a contemptible person on whom royal majesty had not been conferred; he shall come in without warning and obtain the kingdom through intrigue.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 22, 'Armies shall be utterly swept away and broken before him, and the prince of the covenant as well.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 23, 'And after an alliance is made with him, he shall act deceitfully and become strong with a small party.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 24, 'Without warning he shall come into the richest parts of the province and do what none of his predecessors had ever done, lavishing plunder, spoil, and wealth on them. He shall devise plans against strongholds, but only for a time.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 25, 'He shall stir up his power and determination against the king of the south with a great army, and the king of the south shall wage war with a much greater and stronger army. But he shall not succeed, for plots shall be devised against him', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 26, 'by those who eat of the royal rations. They shall break him, his army shall be swept away, and many shall fall slain.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 27, 'The two kings, their minds bent on evil, shall sit at one table and exchange lies. But it shall not succeed, for there remains an end at the time appointed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 28, 'He shall return to his land with great wealth, but his heart shall be set against the holy covenant. He shall work his will, and return to his own land.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 29, '"At the time appointed he shall return and come into the south, but this time it shall not be as it was before.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 30, 'For ships of Kittim shall come against him, and he shall lose heart and withdraw. He shall be enraged and take action against the holy covenant. He shall turn back and pay heed to those who forsake the holy covenant.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 31, 'Forces sent by him shall occupy and profane the temple and fortress. They shall abolish the regular burnt offering and set up the abomination that makes desolate.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 32, 'He shall seduce with intrigue those who violate the covenant; but the people who are loyal to their God shall stand firm and take action.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 33, 'The wise among the people shall give understanding to many; for some days, however, they shall fall by sword and flame, and suffer captivity and plunder.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 34, 'When they fall victim, they shall receive a little help, and many shall join them insincerely.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 35, 'Some of the wise shall fall, so that they may be refined, purified, and cleansed, until the time of the end, for there is still an interval until the time appointed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 36, '"The king shall act as he pleases. He shall exalt himself and consider himself greater than any god, and shall speak horrendous things against the God of gods. He shall prosper until the period of wrath is completed, for what is determined shall be done.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 37, 'He shall pay no respect to the gods of his ancestors, or to the one beloved by women; he shall pay no respect to any other god, for he shall consider himself greater than all.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 38, 'He shall honor the god of fortresses instead of these; a god whom his ancestors did not know he shall honor with gold and silver, with precious stones and costly gifts.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 39, 'He shall deal with the strongest fortresses by the help of a foreign god. Those who acknowledge him he shall make more wealthy, and shall appoint them as rulers over many, and shall distribute the land for a price.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 40, '"At the time of the end the king of the south shall attack him. But the king of the north shall rush upon him like a whirlwind, with chariots and horsemen, and with many ships. He shall advance against countries and pass through like a flood.', 'en', 'NRSV-CE', 'The Time of the End'),
(27, 'Dan', 'Daniel', 11, 41, 'He shall come into the beautiful land, and tens of thousands shall fall victim, but Edom and Moab and the main part of the Ammonites shall escape from his power.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 42, 'He shall stretch out his hand against the countries, and the land of Egypt shall not escape.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 43, 'He shall become ruler of the treasures of gold and of silver, and all the riches of Egypt; and the Libyans and the Ethiopians shall follow in his train.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 44, 'But reports from the east and the north shall alarm him, and he shall go out with great fury to bring ruin and complete destruction to many.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 11, 45, 'He shall pitch his palatial tents between the sea and the beautiful holy mountain. Yet he shall come to his end, with no one to help him.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 12, 1, '"At that time Michael, the great prince, the protector of your people, shall arise. There shall be a time of anguish, such as has never occurred since nations first came into existence. But at that time your people shall be delivered, everyone who is found written in the book.', 'en', 'NRSV-CE', 'The Resurrection of the Dead'),
(27, 'Dan', 'Daniel', 12, 2, 'Many of those who sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 3, 'Those who are wise shall shine like the brightness of the sky, and those who lead many to righteousness, like the stars forever and ever.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 4, 'But you, Daniel, keep the words secret and the book sealed until the time of the end. Many shall be running back and forth, and evil shall increase."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 5, 'Then I, Daniel, looked, and two others appeared, one standing on this bank of the stream and one on the other.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 6, 'One of them said to the man clothed in linen, who was upstream, "How long shall it be until the end of these wonders?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 7, 'The man clothed in linen, who was upstream, raised his right hand and his left hand toward heaven. And I heard him swear by the one who lives forever that it would be for a time, two times, and half a time, and that when the shattering of the power of the holy people comes to an end, all these things would be accomplished.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 8, 'I heard but could not understand; so I said, "My lord, what shall be the outcome of these things?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 9, 'He said, "Go your way, Daniel, for the words are to remain secret and sealed until the time of the end.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 10, 'Many shall be purified, cleansed, and refined, but the wicked shall continue to act wickedly. None of the wicked shall understand, but those who are wise shall understand.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 11, 'From the time that the regular burnt offering is taken away and the abomination that desolates is set up, there shall be one thousand two hundred ninety days.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 12, 'Happy are those who persevere and attain the thousand three hundred thirty-five days.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 12, 13, 'But you, go your way, and rest; you shall rise for your reward at the end of the days."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 13, 1, 'There was a man living in Babylon whose name was Joakim.', 'en', 'NRSV-CE', 'Susanna"s Beauty Attracts Two Elders'),
(27, 'Dan', 'Daniel', 13, 2, 'He married the daughter of Hilkiah, named Susanna, a very beautiful woman and one who feared the Lord.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 3, 'Her parents were righteous, and had trained their daughter according to the law of Moses.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 4, 'Joakim was very rich, and had a fine garden adjoining his house; the Jews used to come to him because he was the most honored of them all.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 5, 'That year two elders from the people were appointed as judges. Concerning them the Lord had said: "Wickedness came forth from Babylon, from elders who were judges, who were supposed to govern the people."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 6, 'These men were frequently at Joakim"s house, and all who had a case to be tried came to them there.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 7, 'When the people left at noon, Susanna would go into her husband"s garden to walk.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 8, 'Every day the two elders used to see her, going in and walking about, and they began to lust for her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 9, 'They suppressed their consciences and turned away their eyes from looking to Heaven or remembering their duty to administer justice.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 10, 'Both were overwhelmed with passion for her, but they did not tell each other of their distress,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 11, 'for they were ashamed to disclose their lustful desire to seduce her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 12, 'Day after day they watched eagerly to see her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 13, 'One day they said to each other, "Let us go home, for it is time for lunch." So they both left and parted from each other.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 14, 'But turning back, they met again; and when each pressed the other for the reason, they confessed their lust. Then together they arranged for a time when they could find her alone.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 15, 'Once, while they were watching for an opportune day, she went in as before with only two maids, and wished to bathe in the garden, for it was a hot day.', 'en', 'NRSV-CE', 'The Elders Attempt to Seduce Susanna'),
(27, 'Dan', 'Daniel', 13, 16, 'No one was there except the two elders, who had hidden themselves and were watching her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 17, 'She said to her maids, "Bring me olive oil and ointments, and shut the garden doors so that I can bathe."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 18, 'They did as she told them: they shut the doors of the garden and went out by the side doors to bring what they had been commanded; they did not see the elders, because they were hiding.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 19, 'When the maids had gone out, the two elders got up and ran to her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 20, 'They said, "Look, the garden doors are shut, and no one can see us. We are burning with desire for you; so give your consent, and lie with us.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 21, 'If you refuse, we will testify against you that a young man was with you, and this was why you sent your maids away."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 22, 'Susanna groaned and said, "I am completely trapped. For if I do this, it will mean death for me; if I do not, I cannot escape your hands.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 23, 'I choose not to do it; I will fall into your hands, rather than sin in the sight of the Lord."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 24, 'Then Susanna cried out with a loud voice, and the two elders shouted against her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 25, 'And one of them ran and opened the garden doors.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 26, 'When the people in the house heard the shouting in the garden, they rushed in at the side door to see what had happened to her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 27, 'And when the elders told their story, the servants felt very much ashamed, for nothing like this had ever been said about Susanna.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 28, 'The next day, when the people gathered at the house of her husband Joakim, the two elders came, full of their wicked plot to have Susanna put to death. In the presence of the people they said,', 'en', 'NRSV-CE', 'The Elders Testify against Susanna'),
(27, 'Dan', 'Daniel', 13, 29, '"Send for Susanna daughter of Hilkiah, the wife of Joakim."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 30, 'So they sent for her. And she came with her parents, her children, and all her relatives.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 31, 'Now Susanna was a woman of great refinement and beautiful in appearance.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 32, 'As she was veiled, the scoundrels ordered her to be unveiled, so that they might feast their eyes on her beauty.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 33, 'Those who were with her and all who saw her were weeping.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 34, 'Then the two elders stood up before the people and laid their hands on her head.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 35, 'Through her tears she looked up toward Heaven, for her heart trusted in the Lord.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 36, 'The elders said, "While we were walking in the garden alone, this woman came in with two maids, shut the garden doors, and dismissed the maids.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 37, 'Then a young man, who was hiding there, came to her and lay with her.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 38, 'We were in a corner of the garden, and when we saw this wickedness we ran to them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 39, 'Although we saw them embracing, we could not hold the man, because he was stronger than we, and he opened the doors and got away.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 40, 'We did, however, seize this woman and asked who the young man was,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 41, 'but she would not tell us. These things we testify."
Because they were elders of the people and judges, the assembly believed them and condemned her to death.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 42, 'Then Susanna cried out with a loud voice, and said, "O eternal God, you know what is secret and are aware of all things before they come to be;', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 43, 'you know that these men have given false evidence against me. And now I am to die, though I have done none of the wicked things that they have charged against me!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 44, 'The Lord heard her cry.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 45, 'Just as she was being led off to execution, God stirred up the holy spirit of a young lad named Daniel,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 46, 'and he shouted with a loud voice, "I want no part in shedding this woman"s blood!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 47, 'All the people turned to him and asked, "What is this you are saying?"', 'en', 'NRSV-CE', 'Daniel Rescues Susanna'),
(27, 'Dan', 'Daniel', 13, 48, 'Taking his stand among them he said, "Are you such fools, O Israelites, as to condemn a daughter of Israel without examination and without learning the facts?', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 49, 'Return to court, for these men have given false evidence against her."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 50, 'So all the people hurried back. And the rest of the elders said to him, "Come, sit among us and inform us, for God has given you the standing of an elder."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 51, 'Daniel said to them, "Separate them far from each other, and I will examine them."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 52, 'When they were separated from each other, he summoned one of them and said to him, "You old relic of wicked days, your sins have now come home, which you have committed in the past,', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 53, 'pronouncing unjust judgments, condemning the innocent and acquitting the guilty, though the Lord said, "You shall not put an innocent and righteous person to death."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 54, 'Now then, if you really saw this woman, tell me this: Under what tree did you see them being intimate with each other?" He answered, "Under a mastic tree."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 55, 'And Daniel said, "Very well! This lie has cost you your head, for the angel of God has received the sentence from God and will immediately cut you in two."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 56, 'Then, putting him to one side, he ordered them to bring the other. And he said to him, "You offspring of Canaan and not of Judah, beauty has beguiled you and lust has perverted your heart.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 57, 'This is how you have been treating the daughters of Israel, and they were intimate with you through fear; but a daughter of Judah would not tolerate your wickedness.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 58, 'Now then, tell me: Under what tree did you catch them being intimate with each other?" He answered, "Under an evergreen oak."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 59, 'Daniel said to him, "Very well! This lie has cost you also your head, for the angel of God is waiting with his sword to split you in two, so as to destroy you both."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 60, 'Then the whole assembly raised a great shout and blessed God, who saves those who hope in him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 61, 'And they took action against the two elders, because out of their own mouths Daniel had convicted them of bearing false witness; they did to them as they had wickedly planned to do to their neighbor.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 62, 'Acting in accordance with the law of Moses, they put them to death. Thus innocent blood was spared that day.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 63, 'Hilkiah and his wife praised God for their daughter Susanna, and so did her husband Joakim and all her relatives, because she was found innocent of a shameful deed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 13, 64, 'And from that day onward Daniel had a great reputation among the people.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(27, 'Dan', 'Daniel', 14, 1, 'When King Astyages was laid to rest with his ancestors, Cyrus the Persian succeeded to his kingdom.', 'en', 'NRSV-CE', 'Daniel and the Priests of Bel'),
(27, 'Dan', 'Daniel', 14, 2, 'Daniel was a companion of the king, and was the most honored of all his Friends.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 3, 'Now the Babylonians had an idol called Bel, and every day they provided for it twelve bushels of choice flour and forty sheep and six measures of wine.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 4, 'The king revered it and went every day to worship it. But Daniel worshiped his own God.
So the king said to him, "Why do you not worship Bel?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 5, 'He answered, "Because I do not revere idols made with hands, but the living God, who created heaven and earth and has dominion over all living creatures."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 6, 'The king said to him, "Do you not think that Bel is a living god? Do you not see how much he eats and drinks every day?"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 7, 'And Daniel laughed, and said, "Do not be deceived, O king, for this thing is only clay inside and bronze outside, and it never ate or drank anything."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 8, 'Then the king was angry and called the priests of Bel and said to them, "If you do not tell me who is eating these provisions, you shall die.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 9, 'But if you prove that Bel is eating them, Daniel shall die, because he has spoken blasphemy against Bel." Daniel said to the king, "Let it be done as you have said."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 10, 'Now there were seventy priests of Bel, besides their wives and children. So the king went with Daniel into the temple of Bel.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 11, 'The priests of Bel said, "See, we are now going outside; you yourself, O king, set out the food and prepare the wine, and shut the door and seal it with your signet.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 12, 'When you return in the morning, if you do not find that Bel has eaten it all, we will die; otherwise Daniel will, who is telling lies about us."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 13, 'They were unconcerned, for beneath the table they had made a hidden entrance, through which they used to go in regularly and consume the provisions.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 14, 'After they had gone out, the king set out the food for Bel. Then Daniel ordered his servants to bring ashes, and they scattered them throughout the whole temple in the presence of the king alone. Then they went out, shut the door and sealed it with the king"s signet, and departed.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 15, 'During the night the priests came as usual, with their wives and children, and they ate and drank everything.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 16, 'Early in the morning the king rose and came, and Daniel with him.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 17, 'The king said, "Are the seals unbroken, Daniel?" He answered, "They are unbroken, O king."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 18, 'As soon as the doors were opened, the king looked at the table, and shouted in a loud voice, "You are great, O Bel, and in you there is no deceit at all!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 19, 'But Daniel laughed and restrained the king from going in. "Look at the floor," he said, "and notice whose footprints these are."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 20, 'The king said, "I see the footprints of men and women and children."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 21, 'Then the king was enraged, and he arrested the priests and their wives and children. They showed him the secret doors through which they used to enter to consume what was on the table.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 22, 'Therefore the king put them to death, and gave Bel over to Daniel, who destroyed it and its temple.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 23, 'Now in that place there was a great dragon, which the Babylonians revered.', 'en', 'NRSV-CE', 'Daniel Kills the Dragon'),
(27, 'Dan', 'Daniel', 14, 24, 'The king said to Daniel, "You cannot deny that this is a living god; so worship him."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 25, 'Daniel said, "I worship the Lord my God, for he is the living God.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 26, 'But give me permission, O king, and I will kill the dragon without sword or club." The king said, "I give you permission."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 27, 'Then Daniel took pitch, fat, and hair, and boiled them together and made cakes, which he fed to the dragon. The dragon ate them, and burst open. Then Daniel said, "See what you have been worshiping!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 28, 'When the Babylonians heard about it, they were very indignant and conspired against the king, saying, "The king has become a Jew; he has destroyed Bel, and killed the dragon, and slaughtered the priests."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 29, 'Going to the king, they said, "Hand Daniel over to us, or else we will kill you and your household."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 30, 'The king saw that they were pressing him hard, and under compulsion he handed Daniel over to them.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 31, 'They threw Daniel into the lions" den, and he was there for six days.', 'en', 'NRSV-CE', 'Daniel in the Lions" Den'),
(27, 'Dan', 'Daniel', 14, 32, 'There were seven lions in the den, and every day they had been given two human bodies and two sheep; but now they were given nothing, so that they would devour Daniel.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 33, 'Now the prophet Habakkuk was in Judea; he had made a stew and had broken bread into a bowl, and was going into the field to take it to the reapers.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 34, 'But the angel of the Lord said to Habakkuk, "Take the food that you have to Babylon, to Daniel, in the lions" den."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 35, 'Habakkuk said, "Sir, I have never seen Babylon, and I know nothing about the den."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 36, 'Then the angel of the Lord took him by the crown of his head and carried him by his hair; with the speed of the wind he set him down in Babylon, right over the den.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 37, 'Then Habakkuk shouted, "Daniel, Daniel! Take the food that God has sent you."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 38, 'Daniel said, "You have remembered me, O God, and have not forsaken those who love you."', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 39, 'So Daniel got up and ate. And the angel of God immediately returned Habakkuk to his own place.', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 40, 'On the seventh day the king came to mourn for Daniel. When he came to the den he looked in, and there sat Daniel!', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 41, 'The king shouted with a loud voice, "You are great, O Lord, the God of Daniel, and there is no other besides you!"', 'en', 'NRSV-CE', NULL),
(27, 'Dan', 'Daniel', 14, 42, 'Then he pulled Daniel out, and threw into the den those who had attempted his destruction, and they were instantly eaten before his eyes.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 1, 1, 'The word of the LORD that came to Hosea son of Beeri, in the days of Kings Uzziah, Jotham, Ahaz, and Hezekiah of Judah, and in the days of King Jeroboam son of Joash of Israel.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 2, 'When the LORD first spoke through Hosea, the LORD said to Hosea, "Go, take for yourself a wife of whoredom and have children of whoredom, for the land commits great whoredom by forsaking the LORD."', 'en', 'NRSV-CE', 'The Family of Hosea'),
(28, 'Hos', 'Hosea', 1, 3, 'So he went and took Gomer daughter of Diblaim, and she conceived and bore him a son.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 4, 'And the LORD said to him, "Name him Jezreel; for in a little while I will punish the house of Jehu for the blood of Jezreel, and I will put an end to the kingdom of the house of Israel.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 5, 'On that day I will break the bow of Israel in the valley of Jezreel."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 6, 'She conceived again and bore a daughter. Then the LORD said to him, "Name her Lo-ruhamah, for I will no longer have pity on the house of Israel or forgive them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 7, 'But I will have pity on the house of Judah, and I will save them by the LORD their God; I will not save them by bow, or by sword, or by war, or by horses, or by horsemen."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 8, 'When she had weaned Lo-ruhamah, she conceived and bore a son.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 9, 'Then the LORD said, "Name him Lo-ammi, for you are not my people and I am not your God."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 1, 10, 'Yet the number of the people of Israel shall be like the sand of the sea, which can be neither measured nor numbered; and in the place where it was said to them, "You are not my people," it shall be said to them, "Children of the living God."', 'en', 'NRSV-CE', 'The Restoration of Israel'),
(28, 'Hos', 'Hosea', 1, 11, 'The people of Judah and the people of Israel shall be gathered together, and they shall appoint for themselves one head; and they shall take possession of the land, for great shall be the day of Jezreel.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 2, 1, 'Say to your brother, Ammi, and to your sister, Ruhamah.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 2, 'Plead with your mother, plead--  
    for she is not my wife,  
    and I am not her husband--  
that she put away her whoring from her face,  
    and her adultery from between her breasts,', 'en', 'NRSV-CE', 'Israel"s Infidelity, Punishment, and Redemption'),
(28, 'Hos', 'Hosea', 2, 3, 'or I will strip her naked  
    and expose her as in the day she was born,  
and make her like a wilderness,  
    and turn her into a parched land,  
    and kill her with thirst.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 4, 'Upon her children also I will have no pity,  
    because they are children of whoredom.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 5, 'For their mother has played the whore;  
    she who conceived them has acted shamefully.  
For she said, "I will go after my lovers;  
    they give me my bread and my water,  
    my wool and my flax, my oil and my drink."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 6, 'Therefore I will hedge up her way with thorns;  
    and I will build a wall against her,  
    so that she cannot find her paths.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 7, 'She shall pursue her lovers,  
    but not overtake them;  
and she shall seek them,  
    but shall not find them.  
Then she shall say, "I will go  
    and return to my first husband,  
    for it was better with me then than now."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 8, 'She did not know  
    that it was I who gave her  
    the grain, the wine, and the oil,  
and who lavished upon her silver  
    and gold that they used for Baal.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 9, 'Therefore I will take back  
    my grain in its time,  
    and my wine in its season;  
and I will take away my wool and my flax,  
    which were to cover her nakedness.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 10, 'Now I will uncover her shame  
    in the sight of her lovers,  
    and no one shall rescue her out of my hand.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 11, 'I will put an end to all her mirth,  
    her festivals, her new moons, her sabbaths,  
    and all her appointed festivals.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 12, 'I will lay waste her vines and her fig trees,  
    of which she said,  
"These are my pay,  
    which my lovers have given me."  
I will make them a forest,  
    and the wild animals shall devour them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 13, 'I will punish her for the festival days of the Baals,  
    when she offered incense to them  
and decked herself with her ring and jewelry,  
    and went after her lovers,  
    and forgot me, says the LORD.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 14, 'Therefore, I will now allure her,  
    and bring her into the wilderness,  
    and speak tenderly to her.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 15, 'From there I will give her her vineyards,  
    and make the Valley of Achor a door of hope.  
There she shall respond as in the days of her youth,  
    as at the time when she came out of the land of Egypt.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 16, 'On that day, says the LORD, you will call me, "My husband," and no longer will you call me, "My Baal."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 17, 'For I will remove the names of the Baals from her mouth, and they shall be mentioned by name no more.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 18, 'I will make for you a covenant on that day with the wild animals, the birds of the air, and the creeping things of the ground; and I will abolish the bow, the sword, and war from the land; and I will make you lie down in safety.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 19, 'And I will take you for my wife forever; I will take you for my wife in righteousness and in justice, in steadfast love, and in mercy.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 20, 'I will take you for my wife in faithfulness; and you shall know the LORD.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 21, 'On that day I will answer, says the LORD,  
    I will answer the heavens  
    and they shall answer the earth;', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 22, 'and the earth shall answer the grain, the wine, and the oil,  
    and they shall answer Jezreel;', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 2, 23, 'and I will sow him for myself in the land.  
And I will have pity on Lo-ruhamah,  
    and I will say to Lo-ammi, "You are my people";  
    and he shall say, "You are my God."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 3, 1, 'The LORD said to me again, "Go, love a woman who has a lover and is an adulteress, just as the LORD loves the people of Israel, though they turn to other gods and love raisin cakes."', 'en', 'NRSV-CE', 'Further Assurances of God"s Redeeming Love'),
(28, 'Hos', 'Hosea', 3, 2, 'So I bought her for fifteen shekels of silver and a homer of barley and a measure of wine.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 3, 3, 'And I said to her, "You must remain as mine for many days; you shall not play the whore, you shall not have intercourse with a man, nor I with you."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 3, 4, 'For the Israelites shall remain many days without king or prince, without sacrifice or pillar, without ephod or teraphim.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 3, 5, 'Afterward the Israelites shall return and seek the LORD their God, and David their king; they shall come in awe to the LORD and to his goodness in the latter days.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 4, 1, 'Hear the word of the LORD, O people of Israel;  
    for the LORD has an indictment against the inhabitants of the land.  
There is no faithfulness or loyalty,  
    and no knowledge of God in the land.', 'en', 'NRSV-CE', 'God Accuses Israel'),
(28, 'Hos', 'Hosea', 4, 2, 'Swearing, lying, and murder,  
    and stealing and adultery break out;  
    bloodshed follows bloodshed.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 3, 'Therefore the land mourns,  
    and all who live in it languish;  
together with the wild animals  
    and the birds of the air,  
    even the fish of the sea are perishing.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 4, 'Yet let no one contend,  
    and let none accuse,  
    for with you is my contention, O priest.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 5, 'You shall stumble by day;  
    the prophet also shall stumble with you by night,  
    and I will destroy your mother.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 6, 'My people are destroyed for lack of knowledge;  
    because you have rejected knowledge,  
    I reject you from being a priest to me.  
And since you have forgotten the law of your God,  
    I also will forget your children.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 7, 'The more they increased,  
    the more they sinned against me;  
    they changed their glory into shame.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 8, 'They feed on the sin of my people;  
    they are greedy for their iniquity.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 9, 'And it shall be like people, like priest;  
    I will punish them for their ways,  
    and repay them for their deeds.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 10, 'They shall eat, but not be satisfied;  
    they shall play the whore, but not multiply;  
because they have forsaken the LORD  
    to devote themselves to', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 11, 'whoredom.
Wine and new wine  
    take away the understanding.', 'en', 'NRSV-CE', 'The Idolatry of Israel'),
(28, 'Hos', 'Hosea', 4, 12, 'My people consult a piece of wood,  
    and their divining rod gives them oracles.  
For a spirit of whoredom has led them astray,  
    and they have played the whore, forsaking their God.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 13, 'They sacrifice on the tops of the mountains,  
    and make offerings upon the hills,  
under oak, poplar, and terebinth,  
    because their shade is good.
Therefore your daughters play the whore,  
    and your daughters-in-law commit adultery.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 14, 'I will not punish your daughters when they play the whore,  
    nor your daughters-in-law when they commit adultery;  
for the men themselves go aside with whores,  
    and sacrifice with temple prostitutes;  
thus a people without understanding comes to ruin.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 15, 'Though you play the whore, O Israel,  
    do not let Judah become guilty.  
Do not enter into Gilgal,  
    or go up to Beth-aven,  
    and do not swear, "As the LORD lives."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 16, 'Like a stubborn heifer,  
    Israel is stubborn;  
can the LORD now feed them  
    like a lamb in a broad pasture?', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 17, 'Ephraim is joined to idols--  
    let him alone.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 18, 'When their drinking is ended, they indulge in sexual orgies;  
    they love lewdness more than their glory.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 4, 19, 'A wind has wrapped them in its wings,  
    and they shall be ashamed because of their altars.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 5, 1, 'Hear this, O priests!  
    Give heed, O house of Israel!  
Listen, O house of the king!  
    For the judgment pertains to you;  
for you have been a snare at Mizpah,  
    and a net spread upon Tabor,', 'en', 'NRSV-CE', 'Impending Judgment on Israel and Judah'),
(28, 'Hos', 'Hosea', 5, 2, 'and a pit dug deep in Shittim;  
    but I will punish all of them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 3, 'I know Ephraim,  
    and Israel is not hidden from me;  
for now, O Ephraim, you have played the whore;  
    Israel is defiled.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 4, 'Their deeds do not permit them  
    to return to their God.  
For the spirit of whoredom is within them,  
    and they do not know the LORD.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 5, 'Israel"s pride testifies against him;  
    Ephraim stumbles in his guilt;  
    Judah also stumbles with them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 6, 'With their flocks and herds they shall go  
    to seek the LORD,  
but they will not find him;  
    he has withdrawn from them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 7, 'They have dealt faithlessly with the LORD;  
    for they have borne illegitimate children.  
    Now the new moon shall devour them along with their fields.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 8, 'Blow the horn in Gibeah,  
    the trumpet in Ramah.  
Sound the alarm at Beth-aven;  
    look behind you, Benjamin!', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 9, 'Ephraim shall become a desolation  
    in the day of punishment;  
among the tribes of Israel  
    I declare what is sure.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 10, 'The princes of Judah have become  
    like those who remove the landmark;  
on them I will pour out  
    my wrath like water.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 11, 'Ephraim is oppressed, crushed in judgment,  
    because he was determined to go after vanity.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 12, 'Therefore I am like maggots to Ephraim,  
    and like rottenness to the house of Judah.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 13, 'When Ephraim saw his sickness,  
    and Judah his wound,  
then Ephraim went to Assyria,  
    and sent to the great king.  
But he is not able to cure you  
    or heal your wound.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 14, 'For I will be like a lion to Ephraim,  
    and like a young lion to the house of Judah.  
I myself will tear and go away;  
    I will carry off, and no one shall rescue.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 5, 15, 'I will return again to my place  
    until they acknowledge their guilt and seek my face.  
    In their distress they will beg my favor:', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 6, 1, '"Come, let us return to the LORD;  
    for it is he who has torn, and he will heal us;  
    he has struck down, and he will bind us up.', 'en', 'NRSV-CE', 'A Call to Repentance'),
(28, 'Hos', 'Hosea', 6, 2, 'After two days he will revive us;  
    on the third day he will raise us up,  
    that we may live before him.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 3, 'Let us know, let us press on to know the LORD;  
    his appearing is as sure as the dawn;  
he will come to us like the showers,  
    like the spring rains that water the earth."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 4, 'What shall I do with you, O Ephraim?  
    What shall I do with you, O Judah?  
Your love is like a morning cloud,  
    like the dew that goes away early.', 'en', 'NRSV-CE', 'Impenitence of Israel and Judah'),
(28, 'Hos', 'Hosea', 6, 5, 'Therefore I have hewn them by the prophets,  
    I have killed them by the words of my mouth,  
    and my judgment goes forth as the light.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 6, 'For I desire steadfast love and not sacrifice,  
    the knowledge of God rather than burnt offerings.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 7, 'But at Adam they transgressed the covenant;  
    there they dealt faithlessly with me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 8, 'Gilead is a city of evildoers,  
    tracked with blood.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 9, 'As robbers lie in wait for someone,  
    so the priests are banded together;  
they murder on the road to Shechem,  
    they commit a monstrous crime.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 10, 'In the house of Israel I have seen a horrible thing;  
    Ephraim"s whoredom is there, Israel is defiled.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 6, 11, 'For you also, O Judah, a harvest is appointed.
When I would restore the fortunes of my people,', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 7, 1, 'when I would heal Israel,  
    the corruption of Ephraim is revealed,  
    and the wicked deeds of Samaria;  
for they deal falsely,  
    the thief breaks in,  
    and the bandits raid outside.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 2, 'But they do not consider  
    that I remember all their wickedness.  
Now their deeds surround them,  
    they are before my face.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 3, 'By their wickedness they make the king glad,  
    and the officials by their treachery.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 4, 'They are all adulterers;  
    they are like a heated oven,  
whose baker does not need to stir the fire,  
    from the kneading of the dough until it is leavened.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 5, 'On the day of our king the officials  
    became sick with the heat of wine;  
    he stretched out his hand with mockers.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 6, 'For they are kindled like an oven, their heart burns within them;  
    all night their anger smolders;  
    in the morning it blazes like a flaming fire.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 7, 'All of them are hot as an oven,  
    and they devour their rulers.  
All their kings have fallen;  
    none of them calls upon me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 8, 'Ephraim mixes himself with the peoples;  
    Ephraim is a cake not turned.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 9, 'Foreigners devour his strength,  
    but he does not know it;  
gray hairs are sprinkled upon him,  
    but he does not know it.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 10, 'Israel"s pride testifies against him;  
    yet they do not return to the LORD their God,  
    or seek him, for all this.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 11, 'Ephraim has become like a dove,  
    silly and without sense;  
    they call upon Egypt, they go to Assyria.', 'en', 'NRSV-CE', 'Futile Reliance on the Nations'),
(28, 'Hos', 'Hosea', 7, 12, 'As they go, I will cast my net over them;  
    I will bring them down like birds of the air;  
    I will discipline them according to the report made to their assembly.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 13, 'Woe to them, for they have strayed from me!  
    Destruction to them, for they have rebelled against me!  
I would redeem them,  
    but they speak lies against me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 14, 'They do not cry to me from the heart,  
    but they wail upon their beds;  
they gash themselves for grain and wine;  
    they rebel against me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 15, 'It was I who trained and strengthened their arms,  
    yet they plot evil against me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 7, 16, 'They turn to that which does not profit;  
    they have become like a defective bow;  
their officials shall fall by the sword  
    because of the rage of their tongue.  
So much for their babbling in the land of Egypt.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 8, 1, 'Set the trumpet to your lips!  
    One like a vulture is over the house of the LORD,  
because they have broken my covenant,  
    and transgressed my law.', 'en', 'NRSV-CE', 'Israel"s Apostasy'),
(28, 'Hos', 'Hosea', 8, 2, 'Israel cries to me,  
    "My God, we--Israel--know you!"', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 3, 'Israel has spurned the good;  
    the enemy shall pursue him.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 4, 'They made kings, but not through me;  
    they set up princes, but without my knowledge.  
With their silver and gold they made idols  
    for their own destruction.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 5, 'Your calf is rejected, O Samaria.  
    My anger burns against them.  
How long will they be incapable of innocence?', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 6, 'For it is from Israel,  
an artisan made it;  
    it is not God.  
The calf of Samaria  
    shall be broken to pieces.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 7, 'For they sow the wind,  
    and they shall reap the whirlwind.  
The standing grain has no heads,  
    it shall yield no meal;  
if it were to yield,  
    foreigners would devour it.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 8, 'Israel is swallowed up;  
    now they are among the nations  
    as a useless vessel.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 9, 'For they have gone up to Assyria,  
    a wild ass wandering alone;  
    Ephraim has bargained for lovers.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 10, 'Though they bargain with the nations,  
    I will now gather them up.  
They shall soon writhe  
    under the burden of kings and princes.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 11, 'When Ephraim multiplied altars to expiate sin,  
    they became to him altars for sinning.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 12, 'Though I write for him the multitude of my instructions,  
    they are regarded as a strange thing.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 13, 'Though they offer choice sacrifices,  
    though they eat flesh,  
    the LORD does not accept them.  
Now he will remember their iniquity,  
    and punish their sins;  
    they shall return to Egypt.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 8, 14, 'Israel has forgotten his Maker,  
    and built palaces;  
and Judah has multiplied fortified cities;  
    but I will send a fire upon his cities,  
    and it shall devour his strongholds.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 9, 1, 'Do not rejoice, O Israel!  
    Do not exult as other nations do;  
for you have played the whore, departing from your God.  
    You have loved a prostitute"s pay  
    on all threshing floors.', 'en', 'NRSV-CE', 'Punishment for Israel"s Sin'),
(28, 'Hos', 'Hosea', 9, 2, 'Threshing floor and wine vat shall not feed them,  
    and the new wine shall fail them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 3, 'They shall not remain in the land of the LORD;  
    but Ephraim shall return to Egypt,  
    and in Assyria they shall eat unclean food.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 4, 'They shall not pour drink offerings of wine to the LORD,  
    and their sacrifices shall not please him.  
Such sacrifices shall be like mourners" bread;  
    all who eat of it shall be defiled;  
for their bread shall be for their hunger only;  
    it shall not come to the house of the LORD.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 5, 'What will you do on the day of appointed festival,  
    and on the day of the festival of the LORD?', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 6, 'For even if they escape destruction,  
    Egypt shall gather them,  
    Memphis shall bury them.  
Nettles shall possess their precious things of silver;  
    thorns shall be in their tents.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 7, 'The days of punishment have come,  
    the days of recompense have come;  
    Israel cries,  
"The prophet is a fool,  
    the man of the spirit is mad!"  
Because of your great iniquity,  
    your hostility is great.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 8, 'The prophet is a sentinel for my God over Ephraim,  
yet a fowler"s snare is on all his ways,  
    and hostility in the house of his God.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 9, 'They have deeply corrupted themselves  
    as in the days of Gibeah;  
he will remember their iniquity,  
    he will punish their sins.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 10, 'Like grapes in the wilderness,  
    I found Israel.  
Like the first fruit on the fig tree,  
    in its first season,  
    I saw your ancestors.  
But they came to Baal-peor,  
    and consecrated themselves to a thing of shame,  
    and became detestable like the thing they loved.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 11, 'Ephraim"s glory shall fly away like a bird--  
    no birth, no pregnancy, no conception!', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 12, 'Even if they bring up children,  
    I will bereave them until no one is left.  
Woe to them indeed  
    when I depart from them!', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 13, 'Once I saw Ephraim as a young palm planted in a lovely meadow,  
    but now Ephraim must lead out his children for slaughter.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 14, 'Give them, O LORD--  
    what will you give?  
Give them a miscarrying womb  
    and dry breasts.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 15, 'Every evil of theirs began at Gilgal;  
    there I came to hate them.  
Because of the wickedness of their deeds  
    I will drive them out of my house.  
I will love them no more;  
    all their officials are rebels.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 16, 'Ephraim is stricken,  
    their root is dried up,  
    they shall bear no fruit.  
Even though they give birth,  
    I will kill the cherished offspring of their womb.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 9, 17, 'Because they have not listened to him,  
    my God will reject them;  
    they shall become wanderers among the nations.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 10, 1, 'Israel is a luxuriant vine  
    that yields its fruit.  
The more his fruit increased  
    the more altars he built;  
as his country improved,  
    he improved his pillars.', 'en', 'NRSV-CE', 'Israel"s Sin and Captivity'),
(28, 'Hos', 'Hosea', 10, 2, 'Their heart is false;  
    now they must bear their guilt.  
The LORD will break down their altars,  
    and destroy their pillars.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 3, 'For now they will say:  
    "We have no king,  
for we do not fear the LORD,  
    and a king--what could he do for us?"', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 4, 'They utter mere words;  
    with empty oaths they make covenants;  
so litigation springs up like poisonous weeds  
    in the furrows of the field.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 5, 'The inhabitants of Samaria tremble  
    for the calf of Beth-aven.  
Its people shall mourn for it,  
    and its idolatrous priests shall wail over it,  
    over its glory that has departed from it.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 6, 'The thing itself shall be carried to Assyria  
    as tribute to the great king.  
Ephraim shall be put to shame,  
    and Israel shall be ashamed of his idol.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 7, 'Samaria"s king shall perish  
    like a chip on the face of the waters.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 8, 'The high places of Aven, the sin of Israel,  
    shall be destroyed.  
Thorn and thistle shall grow up  
    on their altars.  
They shall say to the mountains, Cover us,  
    and to the hills, Fall on us.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 9, 'Since the days of Gibeah you have sinned, O Israel;  
    there they have continued.  
    Shall not war overtake them in Gibeah?', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 10, 'I will come against the wayward people to punish them;  
    and nations shall be gathered against them  
    when they are punished for their double iniquity.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 11, 'Ephraim was a trained heifer  
    that loved to thresh,  
    and I spared her fair neck;  
but I will make Ephraim break the ground;  
    Judah must plow;  
    Jacob must harrow for himself.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 12, 'Sow for yourselves righteousness;  
    reap steadfast love;  
    break up your fallow ground;  
for it is time to seek the LORD,  
    that he may come and rain righteousness upon you.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 13, 'You have plowed wickedness,  
    you have reaped injustice,  
    you have eaten the fruit of lies.  
Because you have trusted in your power  
    and in the multitude of your warriors,', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 14, 'therefore the tumult of war shall rise against your people,  
    and all your fortresses shall be destroyed,  
as Shalman destroyed Beth-arbel on the day of battle  
    when mothers were dashed in pieces with their children.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 10, 15, 'Thus it shall be done to you, O Bethel,  
    because of your great wickedness.  
At dawn the king of Israel  
    shall be utterly cut off.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 11, 1, 'When Israel was a child, I loved him,  
    and out of Egypt I called my son.', 'en', 'NRSV-CE', 'God"s Compassion Despite Israel"s Ingratitude'),
(28, 'Hos', 'Hosea', 11, 2, 'The more I called them,  
    the more they went from me;  
they kept sacrificing to the Baals,  
    and offering incense to idols.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 3, 'Yet it was I who taught Ephraim to walk,  
    I took them up in my arms;  
    but they did not know that I healed them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 4, 'I led them with cords of human kindness,  
    with bands of love.  
I was to them like those  
    who lift infants to their cheeks.  
    I bent down to them and fed them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 5, 'They shall return to the land of Egypt,  
    and Assyria shall be their king,  
    because they have refused to return to me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 6, 'The sword rages in their cities,  
    it consumes their oracle-priests,  
    and devours because of their schemes.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 7, 'My people are bent on turning away from me.  
    To the Most High they call,  
    but he does not raise them up at all.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 8, 'How can I give you up, Ephraim?  
    How can I hand you over, O Israel?  
How can I make you like Admah?  
    How can I treat you like Zeboiim?  
My heart recoils within me;  
    my compassion grows warm and tender.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 9, 'I will not execute my fierce anger;  
    I will not again destroy Ephraim;  
for I am God and no mortal,  
    the Holy One in your midst,  
    and I will not come in wrath.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 10, 'They shall go after the LORD,  
    who roars like a lion;  
when he roars,  
    his children shall come trembling from the west.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 11, 'They shall come trembling like birds from Egypt,  
    and like doves from the land of Assyria;  
    and I will return them to their homes, says the LORD.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 11, 12, 'Ephraim has surrounded me with lies,  
    and the house of Israel with deceit;  
but Judah still walks with God,  
    and is faithful to the Holy One.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 12, 1, 'Ephraim herds the wind,  
    and pursues the east wind all day long;  
they multiply falsehood and violence;  
    they make a treaty with Assyria,  
    and oil is carried to Egypt.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 2, 'The LORD has an indictment against Judah,  
    and will punish Jacob according to his ways,  
    and repay him according to his deeds.', 'en', 'NRSV-CE', 'The Long History of Rebellion'),
(28, 'Hos', 'Hosea', 12, 3, 'In the womb he tried to supplant his brother,  
    and in his manhood he strove with God.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 4, 'He strove with the angel and prevailed,  
    he wept and sought his favor;  
he met him at Bethel,  
    and there he spoke with him.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 5, 'The LORD the God of hosts,  
    the LORD is his name!', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 6, 'But as for you, return to your God,  
    hold fast to love and justice,  
    and wait continually for your God.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 7, 'A trader, in whose hands are false balances,  
    he loves to oppress.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 8, 'Ephraim has said, "Ah, I am rich,  
    I have gained wealth for myself;  
in all of my gain  
    no offense has been found in me  
    that would be sin."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 9, 'I am the LORD your God  
    from the land of Egypt;  
I will make you live in tents again,  
    as in the days of the appointed festival.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 10, 'I spoke to the prophets;  
    it was I who multiplied visions,  
    and through the prophets I will bring destruction.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 11, 'In Gilead there is iniquity,  
    they shall surely come to nothing.  
In Gilgal they sacrifice bulls,  
    so their altars shall be like stone heaps  
    on the furrows of the field.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 12, 'Jacob fled to the land of Aram,  
    there Israel served for a wife,  
    and for a wife he guarded sheep.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 13, 'By a prophet the LORD brought Israel up from Egypt,  
    and by a prophet he was guarded.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 12, 14, 'Ephraim has given bitter offense,  
    so his Lord will bring his crimes down on him  
    and pay him back for his insults.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 13, 1, 'When Ephraim spoke, there was trembling;  
    he was exalted in Israel;  
    but he incurred guilt through Baal and died.', 'en', 'NRSV-CE', 'Relentless Judgment on Israel'),
(28, 'Hos', 'Hosea', 13, 2, 'And now they keep on sinning  
    and make a cast image for themselves,  
idols of silver made according to their understanding,  
    all of them the work of artisans.  
"Sacrifice to these," they say.  
    People are kissing calves!', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 3, 'Therefore they shall be like the morning mist  
    or like the dew that goes away early,  
like chaff that swirls from the threshing floor  
    or like smoke from a window.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 4, 'Yet I have been the LORD your God  
    ever since the land of Egypt;  
you know no God but me,  
    and besides me there is no savior.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 5, 'It was I who fed you in the wilderness,  
    in the land of drought.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 6, 'When I fed them, they were satisfied;  
    they were satisfied, and their heart was proud;  
    therefore they forgot me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 7, 'So I will become like a lion to them,  
    like a leopard I will lurk beside the way.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 8, 'I will fall upon them like a bear robbed of her cubs,  
    and will tear open the covering of their heart;  
there I will devour them like a lion,  
    as a wild animal would mangle them.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 9, 'I will destroy you, O Israel;  
    who can help you?', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 10, 'Where now is your king, that he may save you?  
    Where in all your cities are your rulers,  
of whom you said,  
    "Give me a king and rulers"?', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 11, 'I gave you a king in my anger,  
    and I took him away in my wrath.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 12, 'Ephraim"s iniquity is bound up;  
    his sin is kept in store.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 13, 'The pangs of childbirth come for him,  
    but he is an unwise son;  
for at the proper time he does not present himself  
    at the mouth of the womb.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 14, 'Shall I ransom them from the power of Sheol?  
    Shall I redeem them from Death?  
O Death, where are your plagues?  
    O Sheol, where is your destruction?  
    Compassion is hidden from my eyes.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 15, 'Although he may flourish among rushes,  
    the east wind shall come, a blast from the LORD,  
    rising from the wilderness;  
and his fountain shall dry up,  
    his spring shall be parched.  
It shall strip his treasury  
    of every precious thing.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 13, 16, 'Samaria shall bear her guilt,  
    because she has rebelled against her God;  
they shall fall by the sword,  
    their little ones shall be dashed in pieces,  
    and their pregnant women ripped open.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(28, 'Hos', 'Hosea', 14, 1, 'Return, O Israel, to the LORD your God,  
    for you have stumbled because of your iniquity.', 'en', 'NRSV-CE', 'A Plea for Repentance'),
(28, 'Hos', 'Hosea', 14, 2, 'Take words with you  
    and return to the LORD;  
say to him,  
    "Take away all guilt;  
accept that which is good,  
    and we will offer  
    the fruit of our lips.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 14, 3, 'Assyria shall not save us;  
    we will not ride upon horses;  
we will say no more, "Our God,"  
    to the work of our hands.  
In you the orphan finds mercy."', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 14, 4, 'I will heal their disloyalty;  
    I will love them freely,  
    for my anger has turned from them.', 'en', 'NRSV-CE', 'Assurance of Forgiveness'),
(28, 'Hos', 'Hosea', 14, 5, 'I will be like the dew to Israel;  
    he shall blossom like the lily,  
    he shall strike root like the forests of Lebanon.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 14, 6, 'His shoots shall spread out;  
    his beauty shall be like the olive tree,  
    and his fragrance like that of Lebanon.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 14, 7, 'They shall again live beneath my shadow,  
    they shall flourish as a garden;  
they shall blossom like the vine,  
    their fragrance shall be like the wine of Lebanon.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 14, 8, 'O Ephraim, what have I to do with idols?  
    It is I who answer and look after you.  
I am like an evergreen cypress;  
    your faithfulness comes from me.', 'en', 'NRSV-CE', NULL),
(28, 'Hos', 'Hosea', 14, 9, 'Those who are wise understand these things;  
    those who are discerning know them.  
For the ways of the LORD are right,  
    and the upright walk in them,  
    but transgressors stumble in them.', 'en', 'NRSV-CE', NULL);

